using System.Linq.Expressions;
using BookInventory.BuildingBlocks.Application;
using BookInventory.BuildingBlocks.Domain;
using BookInventory.BuildingBlocks.Persistence.Naming;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata;
using Microsoft.EntityFrameworkCore.Storage.ValueConversion;

namespace BookInventory.BuildingBlocks.Persistence
{
    /// <summary>
    /// Base DbContext for every service. On top of plain EF Core it applies the shared conventions:
    /// <list type="bullet">
    /// <item>UUID v7 keys generated by the application (never by the database);</item>
    /// <item>singular snake_case table names, enums stored as UPPER_SNAKE text with a CHECK constraint;</item>
    /// <item>soft delete: <c>Remove</c> becomes <c>is_deleted = true</c> and reads hide deleted rows (named query filter);</item>
    /// <item>audit columns stamped in UTC from <see cref="ICurrentUser"/>;</item>
    /// <item>optimistic concurrency on aggregate roots (<c>RowVersion</c> = PostgreSQL <c>xmin</c>);</item>
    /// <item>foreign keys default to <c>ON DELETE RESTRICT</c>;</item>
    /// <item>domain events dispatched after the data is saved (inside the open transaction).</item>
    /// </list>
    /// Derive from it and override <see cref="ConfigureModel"/> instead of <c>OnModelCreating</c>.
    /// </summary>
    public abstract class BuildingBlocksDbContext : DbContext
    {
        public const string SoftDeleteFilterKey = "SoftDelete";

        private readonly ICurrentUser? _currentUser;
        private readonly IDomainEventDispatcher? _eventDispatcher;
        private readonly TimeProvider _timeProvider;

        protected BuildingBlocksDbContext(
            DbContextOptions options,
            ICurrentUser? currentUser = null,
            IDomainEventDispatcher? eventDispatcher = null,
            TimeProvider? timeProvider = null) : base(options)
        {
            _currentUser = currentUser;
            _eventDispatcher = eventDispatcher;
            _timeProvider = timeProvider ?? TimeProvider.System;
        }

        /// <summary>Entity configuration for the derived context (<c>ApplyConfigurationsFromAssembly</c> etc.).</summary>
        protected virtual void ConfigureModel(ModelBuilder modelBuilder) { }

        protected sealed override void OnModelCreating(ModelBuilder modelBuilder)
        {
            base.OnModelCreating(modelBuilder);
            ConfigureModel(modelBuilder);

            // Runs after ConfigureModel so entities registered there are covered too.
            foreach (var foreignKey in modelBuilder.Model.GetEntityTypes().SelectMany(t => t.GetForeignKeys()))
            {
                // EF defaults required relationships to ON DELETE CASCADE; a hard cascade would silently wipe
                // child rows (ledger entries...) that soft delete is meant to keep. Explicit settings are respected.
                if (!foreignKey.IsOwnership
                    && ((IConventionForeignKey)foreignKey).GetDeleteBehaviorConfigurationSource() == ConfigurationSource.Convention)
                {
                    foreignKey.DeleteBehavior = DeleteBehavior.Restrict;
                }
            }

            foreach (var entityType in modelBuilder.Model.GetEntityTypes()
                         .Where(t => typeof(DomainBase).IsAssignableFrom(t.ClrType)).ToList())
            {
                if (entityType.BaseType is not null)
                    continue;

                // Keys are UUID v7 values assigned in the constructor, never generated by the database.
                entityType.FindProperty(nameof(DomainBase.Id))!.ValueGenerated = ValueGenerated.Never;

                // A DbSet property name would otherwise become the table name (plural); the class name (singular) wins
                // unless the entity's configuration chose one explicitly.
                if (((IConventionEntityType)entityType).GetTableNameConfigurationSource() == ConfigurationSource.Convention)
                    entityType.SetTableName(SnakeCase.Convert(entityType.ClrType.Name));

                ApplyEnumConvention(entityType);

                if (typeof(AggregateRoot).IsAssignableFrom(entityType.ClrType))
                {
                    var root = modelBuilder.Entity(entityType.ClrType);
                    root.Ignore(nameof(AggregateRoot.DomainEvents));
                    // uint row version => PostgreSQL xmin system column (no extra column, optimistic concurrency).
                    root.Property<uint>(nameof(AggregateRoot.RowVersion)).IsRowVersion();
                }

                var parameter = Expression.Parameter(entityType.ClrType, "e");
                var notDeleted = Expression.Not(Expression.Property(parameter, nameof(DomainBase.IsDeleted)));
                entityType.SetQueryFilter(SoftDeleteFilterKey, Expression.Lambda(notDeleted, parameter));
            }

            NormalizeConstraintNames(modelBuilder.Model);
        }

        /// <summary>
        /// Key, foreign key and index names are derived from table names, but some are computed while a table still
        /// carries its temporary DbSet-based name. Once every table name is final, re-derive the names that were not set
        /// explicitly so they always match the real (singular) table names: <c>pk_widget</c>, <c>fk_part_widget_widget_id</c>,
        /// <c>ix_part_widget_id</c>. These names end up in migrations, so they must be stable and predictable.
        /// </summary>
        private static void NormalizeConstraintNames(IMutableModel model)
        {
            foreach (var entityType in model.GetEntityTypes().Where(t => t.GetTableName() is not null))
            {
                var table = entityType.GetTableName()!;
                string Columns(IEnumerable<IReadOnlyProperty> properties) =>
                    string.Join("_", properties.Select(p => SnakeCase.Convert(p.Name)));

                foreach (var key in entityType.GetDeclaredKeys().Cast<IConventionKey>())
                {
                    if (key.GetNameConfigurationSource() != ConfigurationSource.Convention)
                        continue;
                    ((IMutableKey)key).SetName(key.IsPrimaryKey()
                        ? $"pk_{table}"
                        : $"ak_{table}_{Columns(key.Properties)}");
                }

                foreach (var foreignKey in entityType.GetDeclaredForeignKeys())
                {
                    if (((IConventionForeignKey)foreignKey).GetConstraintNameConfigurationSource() != ConfigurationSource.Convention)
                        continue;
                    var principalTable = foreignKey.PrincipalEntityType.GetTableName();
                    if (principalTable is null)
                        continue;
                    foreignKey.SetConstraintName($"fk_{table}_{principalTable}_{Columns(foreignKey.Properties)}");
                }

                foreach (var index in entityType.GetDeclaredIndexes())
                {
                    if (((IConventionIndex)index).GetDatabaseNameConfigurationSource() != ConfigurationSource.Convention
                        || index.Name is not null)
                        continue;
                    index.SetDatabaseName($"ix_{table}_{Columns(index.Properties)}");
                }
            }
        }

        /// <summary>Enums become UPPER_SNAKE text plus a CHECK constraint listing the allowed values.</summary>
        private static void ApplyEnumConvention(IMutableEntityType entityType)
        {
            foreach (var property in entityType.GetDeclaredProperties())
            {
                var enumType = Nullable.GetUnderlyingType(property.ClrType) ?? property.ClrType;
                if (!enumType.IsEnum || property.GetValueConverter() is not null || property.IsShadowProperty())
                    continue;

                var converter = (ValueConverter)Activator.CreateInstance(
                    typeof(UpperSnakeEnumConverter<>).MakeGenericType(enumType))!;
                property.SetValueConverter(converter);

                var table = entityType.GetTableName() ?? SnakeCase.Convert(entityType.ClrType.Name);
                var column = SnakeCase.Convert(property.Name);
                var allowed = string.Join(", ", Enum.GetNames(enumType).Select(n => $"'{SnakeCase.ConvertUpper(n)}'"));
                entityType.AddCheckConstraint($"ck_{table}_{column}", $"\"{column}\" IN ({allowed})");
            }
        }

        /// <summary>Stamps audit columns on one entity.</summary>
        private void StampAudit(DomainBase entity, bool isNew, bool keepUpdatedBy = false)
        {
            var now = _timeProvider.GetUtcNow().UtcDateTime;
            var userId = _currentUser?.UserId ?? Guid.Empty;

            if (isNew && entity is TransactionDomainBase created)
                created.StampCreated(now, userId);
            else if (!isNew && entity is AuditableDomainBase modified)
                modified.StampUpdated(now, userId, keepUpdatedBy);
        }

        public override int SaveChanges(bool acceptAllChangesOnSuccess)
        {
            if (HasPendingDomainEvents())
                throw new InvalidOperationException(
                    "Domain events are pending; call SaveChangesAsync so they can be dispatched.");

            ApplySoftDeleteAndAudit();
            return base.SaveChanges(acceptAllChangesOnSuccess);
        }

        /// <summary>The most save rounds one save may take while event handlers keep leaving changes; more means an event loop.</summary>
        private const int MaxSaveRounds = 5;

        /// <summary>
        /// Saves, then dispatches the domain events of that save. What the handlers write (rows, changes, their own events) is
        /// saved again in further rounds inside the same transaction, at most <see cref="MaxSaveRounds"/> rounds; a longer chain
        /// is a bug and throws. The result is the number of rows written by all rounds.
        /// </summary>
        public override async Task<int> SaveChangesAsync(bool acceptAllChangesOnSuccess, CancellationToken cancellationToken = default)
        {
            var result = 0;
            for (var round = 1; ; round++)
            {
                OnSavingRound();
                ApplySoftDeleteAndAudit();

                var events = CollectDomainEvents();
                result += await base.SaveChangesAsync(acceptAllChangesOnSuccess, cancellationToken);

                if (events.Count > 0 && _eventDispatcher is not null)
                    await _eventDispatcher.DispatchAsync(events, cancellationToken);

                // Without accepting the changes every entry would still look pending, so such a save takes one round only.
                if (!acceptAllChangesOnSuccess || !HasPendingWork())
                    return result;
                if (round == MaxSaveRounds)
                    throw new InvalidOperationException(
                        $"Domain event handlers still left changes after {MaxSaveRounds} save rounds; an event chain is looping.");
            }
        }

        /// <summary>
        /// Runs before every save round (the first save and each round that saves what event handlers wrote), so a derived
        /// context can prepare the rows of that round, for example stamp an owner or capture an audit trail.
        /// </summary>
        protected virtual void OnSavingRound()
        {
        }

        private bool HasPendingWork()
        {
            ChangeTracker.DetectChanges();
            return HasPendingDomainEvents()
                   || ChangeTracker.Entries().Any(e => e.State is EntityState.Added or EntityState.Modified or EntityState.Deleted);
        }

        private void ApplySoftDeleteAndAudit()
        {
            ChangeTracker.DetectChanges();

            foreach (var entry in ChangeTracker.Entries<DomainBase>().Where(e => e.State == EntityState.Deleted).ToList())
            {
                entry.Entity.MarkDeleted();
                entry.State = EntityState.Modified;
            }

            foreach (var entry in ChangeTracker.Entries<DomainBase>()
                         .Where(e => e.State is EntityState.Added or EntityState.Modified).ToList())
            {
                // A caller that set UpdatedBy explicitly wins over the ambient user.
                var keepUpdatedBy = entry is { State: EntityState.Modified, Entity: AuditableDomainBase }
                                    && entry.Property(nameof(AuditableDomainBase.UpdatedBy)).IsModified;

                StampAudit(entry.Entity, isNew: entry.State == EntityState.Added, keepUpdatedBy);
            }
        }

        private bool HasPendingDomainEvents() =>
            ChangeTracker.Entries<AggregateRoot>().Any(e => e.Entity.DomainEvents.Count > 0);

        private List<IDomainEvent> CollectDomainEvents()
        {
            var entities = ChangeTracker.Entries<AggregateRoot>()
                .Select(e => e.Entity)
                .Where(e => e.DomainEvents.Count > 0)
                .ToList();

            var events = entities.SelectMany(e => e.DomainEvents).ToList();
            entities.ForEach(e => e.ClearDomainEvents());
            return events;
        }
    }
}
